function path(collection:string,id:string){guard();const result=collection+'/'+prefix+id;own(result);return result;}
async function put(path:string,data:any){guard();if(!owned.has(path))throw Error('비소유 쓰기');await db.doc(path).set(data);}
async function cleanup(final=false){for(const path of final?owned:activeOwned){guard();await db.doc(path).delete();expect((await db.doc(path).get()).exists).toBe(false);}activeOwned.clear();}
async function seed(count=1,lineId='line'){
 const order=path('orders','order'),product=path('items','product'),raw=path('items','raw'),formula=path('item_formula','formula'),employee=path('employees','employee');
 const rawId=raw.split('/')[1],productId=product.split('/')[1],statePath='rawInventories/'+inventoryDocId('taebaek',rawId);own(statePath);
 const lot={id:prefix+'rawlot',material:'통깨참기름',supplierName:'합성',kgIn:100,kgRemaining:100,receivedDate:'2026-10-01',status:'active',createdAt:clock.now};
 await put(employee,{authUid:actor.uid,companyId:'taebaek',name:'합성 직원',status:'working'});
 await put(raw,{name:'통깨참기름',rawMaterialName:'통깨참기름',companyId:'taebaek',type:'wip',subtype:'벌크',unit:'kg',stock:100,lots:[lot]});
 await put(statePath,{...emptyRawInventory('taebaek',rawId,'통깨참기름',clock.now),stockKg:100,activeLots:[lot]});
 await put(product,{companyId:'taebaek',name:prefix+'합성품',type:'product',unit:'개',spec:'1kg',stock:0,native:Timestamp.fromMillis(12),geo:new GeoPoint(37,127)});
 await put(formula,{companyId:'taebaek',parent_key:prefix+'합성품',child_name:'통깨참기름',ratio:1});
 const materials=[];for(let i=0;i<count;i++){const material=path('items','material'+i),bom=path('item_bom','bom'+i);materials.push(material);await put(material,{companyId:'taebaek',name:prefix+'포장'+i,type:'submaterial',unit:'개',stock:20,inventoryReservations:[{unknown:'다른행'}]});await put(bom,{companyId:'taebaek',parent_id:productId,child_id:material.split('/')[1],quantity:1});}
 await put(order,{companyId:'taebaek',status:'PROCESSING',partnerName:'합성 고객',items:[{itemId:productId,quantity:3,lineId,checked:true}],note:'원문',createdAt:clock.now});
 const intent={version:1,requestId:prefix+'request',companyId:'taebaek',orderId:order.split('/')[1],action:'status-forward',targetStatus:'DISPATCHED'},reference={version:1 as const,requestId:intent.requestId,companyId:'taebaek' as const,orderId:intent.orderId};own(FULL_ATTEMPTS+'/'+fullAttemptId(reference,actor.uid));
 return {order,product,raw,statePath,materials,intent,reference};
}
async function call(input:any,source=db,identity=actor,at=clock,serverOptions?:Parameters<typeof execute>[4]){guard();const result=await execute(source,identity,input,at,serverOptions);if(result.attemptId){own(FULL_ATTEMPTS+'/'+result.attemptId);const saved=(await db.collection(FULL_ATTEMPTS).doc(result.attemptId).get()).data();if(saved?.fullPlanText){const plan=fullCodec(db).decode(saved.fullPlanText);for(const row of [...plan.readSet,...plan.effectSet])if(!['employees','partners'].includes(row.path.split('/')[0]))own(row.path);own('orderStatusAudits/'+plan.audit.id);}}return result;}
