async function seedLine(count=1){const f=await seed(count),order=(await db.doc(f.order).get()).data()!;order.status='PENDING';order.items=[{...order.items[0],checked:false},{...order.items[0],lineId:'line2',quantity:2,checked:false,note:'최신줄'}];await db.doc(f.order).set(order);const intent:any={version:1,requestId:f.intent.requestId,companyId:'taebaek',orderId:f.intent.orderId,action:'line-forward',target:{index:0,lineId:order.items[0].lineId,itemId:order.items[0].itemId},expectedTarget:order.items[0]};return {...f,intent};}
async function nextLine(f:Awaited<ReturnType<typeof seedLine>>,index=1,requestSuffix='line-next-request'){const order=(await db.doc(f.order).get()).data()!,row=order.items[index];f.intent={...f.intent,action:'line-forward',requestId:prefix+requestSuffix,target:{index,lineId:row.lineId,itemId:row.itemId},expectedTarget:row};f.reference={...f.reference,requestId:f.intent.requestId};own(FULL_ATTEMPTS+'/'+fullAttemptId(f.reference,actor.uid));}
